       num_(NON_LAZY_STRING_PRIM_TAG) {
   assert(str && "Invalid string primitive pointer");
   llvh::SmallVector<char16_t, 32> storage{};
@@ -314,8 +314,6 @@ IdentifierTable::allocateDynamicString(
 }

